pub struct Contract { customer: Customer, supplier: Supplier, start: Date } // private fields

impl TryFrom<ContractDraft> for Contract {
    type Error = ContractError;
    fn try_from(d: ContractDraft) -> Result<Self, Self::Error> {
        let customer = d.customer.ok_or(ContractError::MissingCustomer)?;
        let supplier = d.supplier.ok_or(ContractError::MissingSupplier)?;
        if d.start < today() { return Err(ContractError::StartInPast); }
        Ok(Contract { customer, supplier, start: d.start })  // valid by construction
    }
}
// client: let contract = Contract::try_from(draft)?;  // the only way to obtain a Contract

